
import pandas as pd

# Load the cleaned dataset generated by spotify_analysis_offline.py
df = pd.read_csv("weeknd_tracks_clean.csv")

print("=== DATASET OVERVIEW ===")
print("Rows:", len(df))
print("Columns:", len(df.columns))

print("\n=== MISSING COLLABORATOR VALUES ===")
print("Missing collaborators:",
      df["collaborators"].isna().sum())

print("\nMissing collaborators by collaboration flag:")
print(
    df.groupby("is_collab")["collaborators"]
      .apply(lambda s: s.isna().sum())
)

print("\nMissing collaborators by collaborator count:")
print(
    df.groupby("n_collaborators")["collaborators"]
      .apply(lambda s: s.isna().sum())
)
